import { useState } from "react";
export default function Arraystate() {
  const [devicse, setdvice] = useState("");
  const [arrdvices, setarrdvis] = useState([
    { id: 1, name: "14Pro" },
    { id: 2, name: "15Pro" },
    { id: 3, name: "16Pro" },
  ]);
  const dviselist = arrdvices.map((d) => {
    return (
      <li key={d.id}>
        {d.name}{" "}
        <button
          onClick={() => {
            dleateitem(d.id);
          }}
        >
          dealte
        </button>
        <button
          onClick={() => {
            edititem(d.id);
          }}
        >
          edit
        </button>
      </li>
    );
  });
  function dleateitem(id) {
    const dleate = arrdvices.filter((d) => {
      return d.id !== id;
    });
    setarrdvis(dleate);
  }
  function edititem(id) {
    const dleate = arrdvices.map((d) => {
      if (d.id == id) {
        let newdvice = { ...arrdvices, name: d.name + "0" };
      }
    });
    setarrdvis(dleate);
  }
  return (
    <div className="list">
      {dviselist}
      <div>
        <input
          value={devicse}
          onChange={(d) => {
            setdvice(d.target.value);
          }}
        ></input>
        <button
          onClick={() => {
            setarrdvis([
              ...arrdvices,
              { id: arrdvices.length + 1, name: devicse },
            ]);
          }}
        >
          +
        </button>
      </div>
    </div>
  );
}
